// W38 SMC owner alert, 18 Oct 2026 / owner rule 24 Oct 2026: new SortMyCover leads, bookings, console escalations and booking
// changes -> one minimised WhatsApp to the owner from the SMC number through smc-whatsapp-send (lib/owner-alert.mjs), EMMA
// /api/notify only as the fallback; watermark in static data, committed only after the sender answered ok (or EMMA 2xx).
// Run: node --test automation/tests/W38.test.mjs
// Logic: automation/lib/w38.mjs. Structure: automation/W38.json (generated by automation/build-w38.mjs).
import test from 'node:test';
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { execFileSync } from 'node:child_process';
import { createRequire } from 'node:module';
import { runCode, ifBranch, lvViolations, PG_CRED } from './_n8ncode.mjs';
import { checkSql, workflowSql } from './_sqlcheck.mjs';
import * as L from '../lib/w38.mjs';
import * as S from '../lib/sub-whatsapp-send.mjs';

const WF = JSON.parse(readFileSync(new URL('../W38.json', import.meta.url), 'utf8'));
const { senderKind, findUngated } = createRequire(import.meta.url)('../lib/egress-gate.cjs');
const START = 'Start tick (w38.start: gate + window)';
const READ = 'Read new SMC leads, bookings, escalations, changes';
const PLAN = 'Plan alert (w38.plan)';
const OWNER = 'Owner WhatsApp item (w38.ownerItems)';
const OWNER_SEND = 'Owner WhatsApp (smc-whatsapp-send)';
const OWNER_OK = 'WhatsApp sent? (ok)';
const SEND = 'Notify Jono (EMMA /api/notify, fallback)';
const GATE = `Live send? (${SEND})`;
const STUB = `Dry-run stub (${SEND})`;
const COMMIT = 'Commit or hold (w38.commit)';
const FAILING = 'Third failure in a row?';
const ON = { SMC_LEAD_ALERT_ENABLED: 'true' };
const OWNER_ENV = { OPS_WHATSAPP_JONATHAN: '+27725548057', TWILIO_CONTENT_SIDS: JSON.stringify({ ops_alert: 'HXalert' }) };
const T0 = '2026-10-18T09:00:00.000Z';
const at = (s) => new Date(Date.parse(T0) + s * 1000).toISOString();
const lead = (id, s, over = {}) => ({ kind: 'lead', id, created_at: at(s), first_name: 'Thandi', phone_last3: '234', origin: 'ctwa', ref: 'ad-new-bond', practice: 'SortMyCover test practice', ...over });
const booking = (id, s, over = {}) => ({ kind: 'booking', id, created_at: at(s), at: '2026-10-21T12:30:00+00:00', method: 'teams', status: 'booked', first_name: 'Thandi', phone_last3: '234', practice: 'SortMyCover test practice', ...over });
const escalation = (id, s, over = {}) => ({ kind: 'escalation', id, created_at: at(s), esc: 'other', severity: 'urgent', esc_kind: 'broker_no_show', first_name: 'Thandi', phone_last3: '234', practice: 'Oracle Private Wealth', ...over });
const activity = (id, s, over = {}) => ({ kind: 'activity', id, created_at: at(s), activity: 'booking_moved', at: '2026-10-22T08:00:00Z', first_name: 'Thandi', phone_last3: '234', practice: 'Oracle Private Wealth', ...over });
const node = (name) => WF.nodes.find((n) => n.name === name);
const out = (name, i = 0) => ((WF.connections[name] && WF.connections[name].main[i]) || []).map((t) => t.node);
const SENT = { ok: true, external_id: 'SM0123', error: null, messages: [{ id: 'SM0123' }] };

test('the generated file is current; id, error workflow, lv-automation form, inactive, every minute', () => {
  const before = readFileSync(new URL('../W38.json', import.meta.url), 'utf8');
  execFileSync(process.execPath, [new URL('../build-w38.mjs', import.meta.url).pathname.replace(/^\/([A-Za-z]:)/, '$1')], { stdio: 'pipe' });
  assert.equal(readFileSync(new URL('../W38.json', import.meta.url), 'utf8'), before, 'W38.json is generated by build-w38.mjs');
  assert.deepEqual(lvViolations(WF, 'smc-w38'), []);
  assert.equal(WF.name, 'W38 SMC lead alert (owner)');
  assert.equal(WF.active, false);
  const trig = WF.nodes.filter((n) => n.type === 'n8n-nodes-base.scheduleTrigger');
  assert.deepEqual(trig.map((n) => n.parameters.rule.interval), [[{ field: 'minutes', minutesInterval: 1 }]]);
  const pg = WF.nodes.filter((n) => n.credentials);
  assert.deepEqual(pg.map((n) => [n.name, n.credentials.postgres]), [[READ, { id: '', name: PG_CRED }]], 'Postgres credential by name only, bound at import');
});

test('the query: columns exist in the migrations; email / full number / note / message text never leave the database', () => {
  assert.deepEqual(checkSql(workflowSql(WF)), []);
  const q = node(READ).parameters.query.replace(/--[^\n]*/g, '');
  assert.doesNotMatch(q, /email|\bbody\b|\bmessage\b|id_number|last_name|conv_state|(FROM|JOIN) public\.communications|\.notes\b/i);
  // the number leaves only as its last 3 digits; the test / real split compares it inside the database (a boolean comes back)
  const last3 = q.match(/right\(regexp_replace\(coalesce\(l\.phone, ''\), '\[\^0-9\]', '', 'g'\), 3\)/g).length;
  const compared = q.match(/'test_lead', coalesce\(l\.is_synthetic, false\) OR coalesce\(regexp_replace\(regexp_replace\(regexp_replace\(coalesce\(l\.phone, ''\), [^\n]*= ANY \(string_to_array\(nullif\(\$4, ''\), ','\)\), false\)/g).length;
  assert.equal(compared, 4, 'leads + bookings + escalations + activities');
  assert.equal(q.match(/l\.phone/g).length, last3 + compared);
  assert.match(q, /l\.brand_id = \$1::uuid AND l\.created_at > nullif\(\$2, ''\)::timestamptz/);
  assert.match(q, /a\.brand_id = \$1::uuid AND a\.created_at > nullif\(\$2, ''\)::timestamptz/);
  // escalations: kind / severity / the esc_kind token only; W07's own rows (ref_table communications) are W07's to alert
  assert.match(q, /e\.brand_id = \$1::uuid AND e\.raised_at > nullif\(\$2, ''\)::timestamptz AND coalesce\(e\.ref_table, ''\) <> 'communications'/);
  assert.equal(q.match(/e\.note/g).length, 2, 'the note is read only for its esc_kind= prefix');
  assert.match(q, /CASE WHEN coalesce\(e\.note, ''\) LIKE 'esc_kind=%' THEN split_part\(split_part\(e\.note, ';', 1\), '=', 2\) ELSE '' END/);
  // lead_activities: the short allow-list of types; only payload->>'to' (the new booking time) leaves
  assert.match(q, new RegExp(`la\\.brand_id = \\$1::uuid AND la\\.occurred_at > nullif\\(\\$2, ''\\)::timestamptz AND la\\.activity_type IN \\(${L.ACTIVITY_TYPES.map((t) => `'${t}'`).join(', ')}\\)`));
  assert.deepEqual(q.match(/la\.payload->>'[a-z_]+'/g), ["la.payload->>'to'"]);
  assert.match(q, new RegExp(`LIMIT ${L.ROW_LIMIT}\\)`));
  for (const col of ['l.broker_id', 'a.broker_id', 'e.broker_id', 'la.broker_id']) {
    const c = col.replace('.', '\\.');
    assert.match(q, new RegExp(`'test_practice', CASE WHEN coalesce\\(\\$3, ''\\) = '' OR ${c} IS NULL THEN NULL ELSE ${c}::text = ANY \\(string_to_array\\(\\$3, ','\\)\\) END`), col);
  }
  assert.match(q, /CASE WHEN coalesce\(\$3, ''\) = '' THEN false\s+ELSE \(SELECT count\(\*\) FROM public\.brokers b WHERE b\.id::text = ANY \(string_to_array\(\$3, ','\)\)\) < cardinality\(string_to_array\(\$3, ','\)\) END AS split_unknown_ids/);
  assert.match(q, /'\^0\(\[0-9\]\{9\}\)\$', '27\\1'\)/, 'SA local 0... -> 27... inside the database (one backslash in the SQL)');
  assert.equal(node(READ).parameters.options.queryReplacement, '={{ [ $json.brand_id, $json.since, $json.test_broker_ids || "", $json.test_phones || "" ] }}');
});

test('test / real split (23 Oct 2026): START passes the env lists; lines say the side; wrong side and a bad id list are flagged', async () => {
  const TEST_ID = 'f688380e-fb68-4bfc-a9ee-4bf37ce76dcc';
  const env = { ...ON, SMC_TEST_BROKER_IDS: ` "${TEST_ID.toUpperCase()}" `, SMC_TEST_PHONES: '082 555 0199, +27 83 000 0000', SYNTHETIC_TEST_NUMBERS: '+27600000921' };
  assert.deepEqual(L.splitParams(env), { test_broker_ids: TEST_ID, test_phones: '27600000921,27825550199,27830000000' });
  assert.deepEqual(L.splitParams({}), { test_broker_ids: '', test_phones: '' });
  assert.deepEqual(await runCode(WF, START, { env, staticData: {} }),
    [{ json: { brand_id: L.SMC_BRAND_ID, since: '', test_broker_ids: TEST_ID, test_phones: '27600000921,27825550199,27830000000' } }]);
  // rule off (test_practice null): the line is exactly as before
  assert.equal(L.line(lead('l1', 0, { test_practice: null, test_lead: false })), '- Lead: Thandi, WhatsApp ad (ad-new-bond), phone ends 234, routed to SortMyCover test practice');
  assert.equal(L.line(lead('l1', 0, { test_practice: true, test_lead: true })), '- Lead: Thandi, WhatsApp ad (ad-new-bond), phone ends 234, routed to SortMyCover test practice (TEST practice) [test data]');
  assert.equal(L.line(lead('l1', 0, { practice: 'Oracle Private Wealth', test_practice: false, test_lead: false })), '- Lead: Thandi, WhatsApp ad (ad-new-bond), phone ends 234, routed to Oracle Private Wealth (real adviser)');
  assert.match(L.line(lead('l1', 0, { test_practice: true, test_lead: false })), /\(TEST practice\) \[WRONG SIDE of the test\/real split: check it now\]$/, 'a real lead on the test practice');
  assert.match(L.line(booking('b1', 0, { test_practice: false, synthetic: true })), /\(real adviser\) \[WRONG SIDE of the test\/real split: check it now\] \[test data\]$/, 'a test booking on a real adviser');
  assert.equal(L.line(lead('l1', 0, { practice: null, test_practice: null, test_lead: true })), '- Lead: Thandi, WhatsApp ad (ad-new-bond), phone ends 234, not routed [test data]');
  // split_unknown_ids -> the warning under the head line, through the real PLAN node
  const sd = { watermark: at(0), seen: {} };
  const p = await runCode(WF, PLAN, { items: [{ db_now: at(60), split_unknown_ids: true, items: [lead('l1', 10)] }], staticData: sd });
  assert.equal(p[0].json.message.split('\n')[1], L.SPLIT_WARNING);
  const q = await runCode(WF, PLAN, { items: [{ db_now: at(60), split_unknown_ids: false, items: [lead('l1', 10)] }], staticData: { watermark: at(0), seen: {} } });
  assert.doesNotMatch(q[0].json.message, /SMC_TEST_BROKER_IDS/);
});

test('owner rule (24 Oct 2026): the tick is ONE WhatsApp to the owner from the SMC number through smc-whatsapp-send; EMMA is the fallback', async () => {
  const p = L.plan({ watermark: at(0), seen: {} }, [lead('l1', 10), escalation('e1', 20)], at(60));
  const items = L.ownerItems(p, OWNER_ENV);
  assert.equal(items.length, 1, 'one message per tick, to the owner only');
  const it = items[0];
  assert.deepEqual([it.kind, it.to, it.record, it.caller, it.bypass_suppression, it.correlation], ['prebuilt', '+27725548057', false, 'W38', true, `owner:W38:tick:${at(60)}:owner`]);
  assert.equal(it.wa.template.name, 'ops_alert', 'the approved stopgap until ops_update has a SID');
  assert.deepEqual(it.wa.template.components[0].parameters.map((x) => x.text), ['Jono', '1 new lead, 1 needs a person',
    'Lead: Thandi, WhatsApp ad (ad-new-bond), phone ends 234, routed to SortMyCover test practice | Needs a person (urgent): the lead says the adviser did not call, Thandi, phone ends 234, with Oracle Private Wealth']);
  assert.equal(L.ownerItems(p, { ...OWNER_ENV, TWILIO_CONTENT_SIDS: JSON.stringify({ ops_alert: 'HXa', ops_update: 'HXu' }) })[0].wa.template.name, 'ops_update');
  assert.equal(L.ownerItems(p, { ...OWNER_ENV, SMC_OWNER_WHATSAPP: '+27820000009' })[0].to, '+27820000009', 'Zoe Experience later = SMC_OWNER_WHATSAPP only');
  assert.equal(L.ownerItems(p, {})[0].to, '+27725548057', 'no env at all: the documented default (Jono)');
  // the sender accepts it as is: valid prebuilt, suppression bypassed, a tester number (SMC_TEST_PHONES) is still really sent
  const n = S.normalise(it);
  assert.deepEqual([n.valid, n.record, n.bypass_suppression], [true, false, true]);
  const d = S.decide(n, { suppressed: true }, { SMC_TEST_PHONES: '+27725548057' }, Date.now());
  assert.equal(d.action, 'send');
  assert.equal(S.decide(n, {}, { SYNTHETIC_TEST_NUMBERS: '+27725548057' }, Date.now()).action, 'dry', 'only SYNTHETIC_TEST_NUMBERS dry-runs');
  // the real OWNER node
  const built = await runCode(WF, OWNER, { items: [p], env: OWNER_ENV });
  assert.deepEqual(built.map((x) => [x.json.to, x.json.wa.template.name, x.json.bypass_suppression]), [['+27725548057', 'ops_alert', true]]);
  const sub = node(OWNER_SEND);
  assert.equal(sub.type, 'n8n-nodes-base.executeWorkflow');
  assert.equal(sub.parameters.workflowId.value, 'smc-whatsapp-send');
  assert.equal(sub.parameters.options.waitForSubWorkflow, true, 'the Result decides the commit');
  assert.equal(sub.onError, 'continueRegularOutput', 'a sub failure reaches the ok? check (false) and the fallback');
  assert.equal(ifBranch(WF, OWNER_OK, { json: SENT }), true);
  assert.equal(ifBranch(WF, OWNER_OK, { json: { ok: false, error: 'twilio_content_sid_missing' } }), false);
  assert.equal(ifBranch(WF, OWNER_OK, { json: {} }), false, 'no answer at all -> fallback');
});

test('fallback: POST https://emmadoesit.cloud/api/notify with x-emma-secret from env; body { message, source, title } from the plan', () => {
  const p = node(SEND).parameters;
  assert.equal(p.method, 'POST');
  assert.equal(p.url, 'https://emmadoesit.cloud/api/notify');
  assert.deepEqual(p.headerParameters.parameters, [{ name: 'content-type', value: 'application/json' }, { name: 'x-emma-secret', value: '={{ $env.EMMA_SHARED_SECRET }}' }]);
  assert.equal(p.jsonBody, `={{ JSON.stringify($('${PLAN}').first().json.request) }}`, 'its input is the sender result, so the body comes from the plan');
  assert.equal(p.options.response.response.neverError, true, 'a 502 reaches Commit or hold as a status, not as a node error');
  assert.equal(node(SEND).onError, 'continueRegularOutput', 'no answer at all also reaches Commit or hold');
  assert.deepEqual(L.requestBody('x'), { message: 'x', source: 'smc-lead-alert', title: 'SortMyCover lead' });
  assert.equal(senderKind(node(SEND)), 'notify', 'egress-gate knows EMMA notify as a sender');
  assert.deepEqual(findUngated(WF), [], 'gated on DRY_RUN_SENDS (the WhatsApp sub gates itself)');
});

test('wiring: plan -> owner item -> smc-whatsapp-send -> ok? -> commit | EMMA (DRY_RUN gate -> POST or stub) -> commit -> third failure? -> stop (W22)', () => {
  assert.deepEqual(out('Every minute'), [START]);
  assert.deepEqual(out(START), [READ]);
  assert.deepEqual(out(READ), [PLAN]);
  assert.deepEqual(out(PLAN), [OWNER]);
  assert.deepEqual(out(OWNER), [OWNER_SEND]);
  assert.deepEqual(out(OWNER_SEND), [OWNER_OK]);
  assert.deepEqual([out(OWNER_OK, 0), out(OWNER_OK, 1)], [[COMMIT], [GATE]]);
  assert.deepEqual([out(GATE, 0), out(GATE, 1)], [[SEND], [STUB]]);
  assert.deepEqual(out(SEND), [COMMIT]);
  assert.deepEqual(out(STUB), [COMMIT]);
  assert.deepEqual(out(COMMIT), [FAILING]);
  assert.deepEqual(out(FAILING, 0), ['Fail the run once (W22 emails ops)']);
  assert.equal(node('Fail the run once (W22 emails ops)').type, 'n8n-nodes-base.stopAndError');
  assert.equal(WF.settings.errorWorkflow, 'smc-w22');
});

test('formatter: first name, last 3 digits, source / angle, practice; never email, full number, ID number or message text', () => {
  const wide = lead('l1', 0, { first_name: 'Lerato Dlamini', phone: '+27 82 555 1234', phone_last3: undefined, email: 'lerato@gmail.com',
    id_number: '8001015009087', last_name: 'Dlamini', body: 'my salary is R40k, call me on 0825551234', message: 'hello', angle: 'new-bond' });
  const m = L.format([wide]);
  assert.equal(m, 'SortMyCover: 1 new lead\n- Lead: Lerato, WhatsApp ad (new-bond), phone ends 234, routed to SortMyCover test practice');
  assert.doesNotMatch(m, /lerato@|gmail|555|1234|8001015009087|Dlamini|salary|hello|@/);
  // a name field holding an email or a number is never echoed
  for (const v of ['lerato@gmail.com', '0825551234', '', null, '   ', '😀']) assert.match(L.line(lead('x', 0, { first_name: v })), /^- Lead: name not given yet,/);
  // public attribution values (ref / utm) are cleaned: no email-like token, no long digit runs
  const src = L.sourceText({ origin: 'page', ref: 'x lerato@gmail.com 0825551234 cycle1' });
  assert.equal(src, 'site (x cycle1)');
  assert.equal(L.sourceText({}), '');
  assert.equal(L.line(lead('x', 0, { practice: null, origin: null, ref: null, phone_last3: '' })), '- Lead: Thandi, no number, not routed');
  assert.equal(L.phoneTail('+27 82 555 1234'), '234');
  assert.equal(L.phoneTail('12'), '');
});

