  assert.equal(L.sastText('2026-10-21T12:30:00Z'), 'Wed 21 Oct 14:30 SAST');
  assert.equal(L.sastText('2026-12-31T22:15:00+00:00'), 'Fri 1 Jan 00:15 SAST');
