test('formatter: console escalations and booking changes (24 Oct 2026): kind + severity + esc_kind label, never the note; voice call-backs', () => {
  assert.equal(L.line(escalation('e1', 0)), '- Needs a person (urgent): the lead says the adviser did not call, Thandi, phone ends 234, with Oracle Private Wealth');
  assert.equal(L.line(escalation('e1', 0, { severity: 'red', esc_kind: 'sensitive', practice: null })), '- Needs a person (RED): sensitive chat, Thandi, phone ends 234');
  assert.equal(L.line(escalation('e1', 0, { severity: 'normal', esc_kind: '', esc: 'human_handoff', practice: null, test_lead: true })), '- Needs a person: asked for a person, Thandi, phone ends 234 [test data]');
  assert.equal(L.line(escalation('e1', 0, { severity: 'normal', esc_kind: 'outcome_disputed', esc: 'outcome_unmarked' })), '- Needs a person: outcome disputed, Thandi, phone ends 234, with Oracle Private Wealth');
  assert.equal(L.line(escalation('e1', 0, { severity: 'normal', esc_kind: 'two_unconfirmed', esc: 'other' })), '- Needs a person: two unconfirmed outcomes, Thandi, phone ends 234, with Oracle Private Wealth');
  assert.equal(L.line(escalation('e1', 0, { severity: 'normal', esc_kind: 'second_reschedule', esc: 'other', test_practice: false, test_lead: false })), '- Needs a person: second reschedule, Thandi, phone ends 234, with Oracle Private Wealth (real adviser)');
  // an unknown token is shown as words, never as free text with punctuation or digits
  assert.equal(L.line(escalation('e1', 0, { severity: 'normal', esc_kind: 'new_kind lerato@gmail.com 0825551234', practice: null })), '- Needs a person: new kind, Thandi, phone ends 234');
  assert.equal(L.line(activity('a1', 0)), '- Booking moved: Thandi, to Thu 22 Oct 10:00 SAST, phone ends 234, with Oracle Private Wealth');
  assert.equal(L.line(activity('a1', 0, { activity: 'booking_cancelled', at: null })), '- Booking cancelled: Thandi, phone ends 234, with Oracle Private Wealth');
  assert.equal(L.line(activity('a1', 0, { activity: 'voice_callback_requested', at: null, practice: null })), '- Call-back asked (phone): Thandi, phone ends 234');
  assert.equal(L.line(activity('a1', 0, { activity: 'voice_callback_scheduled', at: null, practice: null })), '- Missed call, automatic call-back set: Thandi, phone ends 234');
  const m = L.format([lead('l1', 0), activity('a1', 1), escalation('e1', 2), escalation('e2', 3)]);
  assert.match(m, /^SortMyCover: 1 new lead, 1 booking change, 2 need a person\n/);
  assert.equal(m.split('\n').length, 5);
  assert.doesNotMatch(JSON.stringify(L.format([escalation('e1', 0, { note: 'esc_kind=broker_no_show; Thandi N.: the lead says Mark did not call', deep_link: '/console/x' })])), /did not call Mark|console\/x/);
  // plan() keeps every kind, each under its own key
  const p = L.plan({ watermark: at(0), seen: {} }, [lead('l1', 10), escalation('e1', 20), activity('a1', 30), { kind: 'weird', id: 'w1', created_at: at(40) }], at(60));
  assert.deepEqual(p.keys, ['lead:l1', 'escalation:e1', 'activity:a1']);
});

test('formatter: long ticks stay short (25 lines, "...and N more", under 3500 characters); the template variable is clipped on a word', () => {
  const many = Array.from({ length: 40 }, (_, i) => lead(`l${i}`, i));
  const m = L.format(many);
  assert.equal(m.split('\n').length, 1 + 25 + 1);
  assert.match(m, /\n\.\.\.and 15 more \(see the CRM\)$/);
  const long = Array.from({ length: 25 }, (_, i) => lead(`l${i}`, i, { practice: 'P'.repeat(200) }));
  assert.ok(L.format(long).length <= L.MAX_CHARS);
  const p = L.plan({ watermark: at(0), seen: {} }, many, at(60));
  const vars = L.ownerItems(p, OWNER_ENV)[0].wa.template.components[0].parameters.map((x) => x.text);
  assert.ok(vars[2].length <= 600 && /\.\.\.$/.test(vars[2]), vars[2].length);
  for (const v of vars) assert.doesNotMatch(v, /[\n\t]| {5,}/, 'WhatsApp template variables: no newlines, tabs or long space runs');
});

test('first run: watermark = db_now, nothing sent, even when rows come back', () => {
  assert.deepEqual(L.start({}, ON), { run: true, brand_id: L.SMC_BRAND_ID, since: '' });
  const p = L.plan({}, [lead('l1', -10), escalation('e0', -5)], at(0));
  assert.equal(p.action, 'init');
  assert.equal(p.next.watermark, at(0));
  assert.equal(p.message, undefined);
  assert.ok('lead:l1' in p.next.seen && 'escalation:e0' in p.next.seen, 'a row seen on the first run is history, never sent later');
});

test('watermark + de-dupe: overlap re-reads, seen ids are skipped, prune keeps the window and at most 200 ids', () => {
  const st = { watermark: at(0), seen: { 'lead:l1': Date.parse(at(-30)) } };
  assert.equal(L.start(st, ON).since, new Date(Date.parse(at(0)) - L.OVERLAP_MS).toISOString(), 'reads from watermark minus the overlap');
  const p = L.plan(st, [lead('l1', -30), lead('l2', -5), booking('b1', 20)], at(60));
  assert.equal(p.action, 'send');
  assert.deepEqual(p.keys, ['lead:l2', 'booking:b1'], 'l1 was sent before; oldest first');
  assert.equal(p.next.watermark, at(60));
  assert.deepEqual(Object.keys(p.next.seen).sort(), ['booking:b1', 'lead:l1', 'lead:l2']);
  assert.deepEqual(p.request, { message: p.message, source: 'smc-lead-alert', title: 'SortMyCover lead' });
  // nothing new -> idle, the watermark still advances
  const idle = L.plan({ ...st, ...p.next }, [lead('l2', -5), booking('b1', 20)], at(120));
  assert.equal(idle.action, 'idle');
  assert.equal(idle.next.watermark, at(120));
  // prune: ids older than the overlap window go; at most SEEN_CAP stay (newest)
  const now = Date.parse(at(0));
  assert.deepEqual(Object.keys(L.prune({ old: now - L.OVERLAP_MS - 120_000, keep: now - 1000 }, now)), ['keep']);
  const big = Object.fromEntries(Array.from({ length: 300 }, (_, i) => [`lead:${i}`, now - i]));
  const pr = L.prune(big, now);
  assert.equal(Object.keys(pr).length, L.SEEN_CAP);
  assert.ok('lead:0' in pr && !('lead:299' in pr));
  // a full page (ROW_LIMIT rows) advances only to its newest row; the watermark never moves back
  const page = Array.from({ length: L.ROW_LIMIT }, (_, i) => lead(`p${i}`, i));
  assert.equal(L.plan({ watermark: at(-1), seen: {} }, page, at(3600)).next.watermark, at(L.ROW_LIMIT - 1));
  assert.equal(L.plan({ watermark: at(500), seen: {} }, [lead('z', 10)], at(400)).next.watermark, at(500));
  assert.equal(L.plan({ watermark: at(0) }, JSON.stringify([lead('s', 1)]), at(5)).items, 1, 'jsonb as text is parsed too');
  assert.throws(() => L.plan({ watermark: at(0) }, [], undefined), /db_now/);
});

test('commit: the sender\'s ok commits (channel whatsapp, Twilio id kept); ok:false holds; EMMA 2xx on the fallback commits as emma; a dry: id is a dry run', () => {
  const st0 = { watermark: at(0), seen: {} };
  const p = L.plan(st0, [lead('l1', 10)], at(60));
  const ok = L.commit(st0, p, SENT, at(61));
  assert.deepEqual([ok.delivered, ok.dry_run, ok.status, ok.channel, ok.state.watermark, ok.state.fails, ok.state.last.external_id, ok.state.last.channel], [true, false, 200, 'whatsapp', at(60), 0, 'SM0123', 'whatsapp']);
  const held = L.commit(st0, p, { ok: false, external_id: null, error: 'twilio_content_sid_missing' }, at(61));
  assert.deepEqual([held.delivered, held.state.watermark, held.state.fails, held.state.last_error.detail], [false, at(0), 1, 'twilio_content_sid_missing']);
  const emma = L.commit(st0, p, { statusCode: 200, body: { delivered: true } }, at(61));
  assert.deepEqual([emma.delivered, emma.channel, emma.state.last.channel], [true, 'emma', 'emma']);
  const dry = L.commit(st0, p, { ok: true, external_id: 'dry:owner:W38:tick:x:owner' }, at(61));
  assert.deepEqual([dry.delivered, dry.dry_run, dry.channel, dry.state.watermark, dry.state.last.message], [false, true, 'dry', at(60), p.message]);
});

test('retry: a held send keeps the old watermark, the next tick resends; the 3rd failure in a row alerts once', () => {
  const st0 = { watermark: at(0), seen: {} };
  const p1 = L.plan(st0, [lead('l1', 10)], at(60));
  const f1 = L.commit(st0, p1, { ok: false, error: 'send_failed' }, at(61));
  assert.deepEqual([f1.delivered, f1.alert, f1.state.watermark, f1.state.fails], [false, false, at(0), 1]);
  assert.deepEqual(f1.state.seen, {}, 'the unsent item is not marked seen');
  const p2 = L.plan(f1.state, [lead('l1', 10), lead('l2', 70)], at(120));
  assert.deepEqual(p2.keys, ['lead:l1', 'lead:l2'], 'the failed item goes again, with the new one');
  const f2 = L.commit(f1.state, p2, { error: { message: 'ETIMEDOUT' } }, at(121));
  assert.deepEqual([f2.state.fails, f2.alert, f2.state.last_error.detail], [2, false, 'ETIMEDOUT']);
  const f3 = L.commit(f2.state, p2, { statusCode: 401, body: { result: 'Unauthorised' } }, at(181));
  assert.deepEqual([f3.state.fails, f3.alert], [3, true]);
  assert.equal(L.commit(f3.state, p2, { statusCode: 502 }, at(241)).alert, false, 'the run fails once per outage, not every minute');
  const ok = L.commit(f3.state, p2, SENT, at(242));
  assert.deepEqual([ok.delivered, ok.state.watermark, ok.state.fails, ok.state.last.items], [true, at(120), 0, 2]);
  assert.ok('lead:l1' in ok.state.seen && 'lead:l2' in ok.state.seen);
  assert.equal(ok.state.last_error, undefined);
});

test('gates: SMC_LEAD_ALERT_ENABLED must be exactly "true"; off drops the state (no replay when switched on again)', async () => {
  for (const v of [undefined, '', 'false', 'TRUE', '1']) {
    assert.equal(L.start({ watermark: at(0) }, { SMC_LEAD_ALERT_ENABLED: v }).run, false);
    const sd = { watermark: at(0), seen: { 'lead:x': 1 }, fails: 2 };
    assert.deepEqual(await runCode(WF, START, { env: { SMC_LEAD_ALERT_ENABLED: v }, staticData: sd }), []);
    assert.deepEqual(sd, {}, 'state dropped');
  }
  const sd = {};
  assert.deepEqual(await runCode(WF, START, { env: ON, staticData: sd }), [{ json: { brand_id: L.SMC_BRAND_ID, since: '', test_broker_ids: '', test_phones: '' } }]);
  assert.deepEqual(L.gates({ DRY_RUN_SENDS: 'true', SMC_LEAD_ALERT_ENABLED: 'true' }), { enabled: true, dryRun: true });
});

test('gates: DRY_RUN_SENDS=true: the sender dry-runs (dry: id) and the fallback takes the stub (no POST); both log the message and advance the watermark', async () => {
  const p = L.plan({ watermark: at(0), seen: {} }, [lead('l1', 10)], at(60));
  // the sender's own dry run (SUB.test.mjs): Result { ok: true, external_id: 'dry:<correlation>' }
  const n = S.normalise(L.ownerItems(p, OWNER_ENV)[0]);
  const dry = S.result(S.decide(n, {}, { DRY_RUN_SENDS: 'true' }, Date.now()));
  assert.equal(dry.ok, true); assert.match(dry.external_id, /^dry:owner:W38:/);
  assert.equal(ifBranch(WF, OWNER_OK, { json: dry }), true);
  const logged = [];
  const log = console.log; console.log = (s) => logged.push(String(s));
  try {
    const sd = { watermark: at(0), seen: {} };
    const r = await runCode(WF, COMMIT, { items: [dry], staticData: sd, refs: { [PLAN]: p } });
    assert.deepEqual(r[0].json, { delivered: false, dry_run: true, status: 200, channel: 'dry', items: 1, fails: 0, alert: false });
    assert.equal(sd.watermark, at(60));
    assert.equal(sd.last.message, p.message);
    // the EMMA fallback under DRY_RUN_SENDS: gate -> stub
    assert.equal(ifBranch(WF, GATE, { json: { ok: false }, env: { DRY_RUN_SENDS: 'true' } }), false, 'dry run -> stub');
    assert.equal(ifBranch(WF, GATE, { json: { ok: false }, env: {} }), true, 'live -> POST');
    const stubbed = await runCode(WF, STUB, { items: [{ ok: false }] });
    assert.equal(stubbed[0].json.dry_run, true);
    const sd2 = { watermark: at(0), seen: {} };
    const r2 = await runCode(WF, COMMIT, { items: [stubbed[0].json], staticData: sd2, refs: { [PLAN]: p } });
    assert.deepEqual(r2[0].json, { delivered: false, dry_run: true, status: 200, channel: 'dry', items: 1, fails: 0, alert: false });
    assert.equal(sd2.watermark, at(60));
  } finally { console.log = log; }
  assert.match(logged.join('\n'), /DRY_RUN_SENDS=true: logged, not sent[\s\S]*- Lead: Thandi/);
});

test('the real nodes across ticks: first run silent, a held send retries, the sender ok sends everything once, EMMA only when the sender says no', async () => {
  const sd = {};
  const tick = async (rows, dbNow, answer) => {
    const s = await runCode(WF, START, { env: ON, staticData: sd });
    if (!s.length) return { stopped: 'start' };
    const planned = await runCode(WF, PLAN, { items: [{ db_now: dbNow, items: rows }], staticData: sd });
    if (!planned.length) return { stopped: 'plan', since: s[0].json.since };
    const p = planned[0].json;
    const built = await runCode(WF, OWNER, { items: [p], env: OWNER_ENV });
    assert.equal(built.length, 1);
    assert.equal(built[0].json.to, '+27725548057');
    const viaWhatsApp = ifBranch(WF, OWNER_OK, { json: answer.sub });
    let res = answer.sub;
    if (!viaWhatsApp) { assert.equal(ifBranch(WF, GATE, { json: answer.sub, env: {} }), true); res = answer.emma; }
    const c = await runCode(WF, COMMIT, { items: [res], staticData: sd, refs: { [PLAN]: p } });
    return { since: s[0].json.since, message: p.message, vars: built[0].json.wa.template.components[0].parameters.map((x) => x.text), commit: c[0].json, failing: ifBranch(WF, FAILING, { json: c[0].json }) };
  };
  const NO = { ok: false, external_id: null, error: 'twilio_content_sid_missing' };
  assert.deepEqual(await tick([], at(0), null), { stopped: 'plan', since: '' }, 'first run: no rows read, nothing sent');
  assert.equal(sd.watermark, at(0));
  const t2 = await tick([lead('l1', 30)], at(60), { sub: NO, emma: { statusCode: 502, body: { delivered: false } } });
  assert.match(t2.message, /^SortMyCover: 1 new lead\n- Lead: Thandi/);
  assert.deepEqual([t2.commit.delivered, t2.commit.fails, t2.failing, sd.watermark], [false, 1, false, at(0)]);
  const t3 = await tick([lead('l1', 30), booking('b1', 90), escalation('e1', 100)], at(120), { sub: SENT });
  assert.equal(t3.since, new Date(Date.parse(at(0)) - L.OVERLAP_MS).toISOString(), 'the window still starts at the held watermark');
  assert.match(t3.message, /^SortMyCover: 1 new lead, 1 new booking, 1 needs a person\n- Lead: Thandi.*\n- Booking: Thandi.*\n- Needs a person \(urgent\)/);
  assert.deepEqual(t3.vars.slice(0, 2), ['Jono', '1 new lead, 1 new booking, 1 needs a person']);
  assert.deepEqual([t3.commit.delivered, t3.commit.channel, t3.commit.fails, sd.watermark, sd.last.external_id], [true, 'whatsapp', 0, at(120), 'SM0123']);
  assert.deepEqual(await tick([lead('l1', 30), booking('b1', 90), escalation('e1', 100)], at(180), null), { stopped: 'plan', since: new Date(Date.parse(at(120)) - L.OVERLAP_MS).toISOString() }, 'the overlap re-read sends nothing twice');
  assert.equal(sd.watermark, at(180));
  // the sender says no, EMMA delivers: committed as the emma channel
  const t5 = await tick([activity('a1', 200)], at(240), { sub: NO, emma: { statusCode: 200, body: { delivered: true } } });
  assert.deepEqual([t5.commit.delivered, t5.commit.channel, sd.watermark], [true, 'emma', at(240)]);
  // three failures in a row (sender no, EMMA 502) -> the IF to "Fail the run once" is true exactly once
  const fails = [];
  for (let i = 0; i < 4; i++) fails.push((await tick([lead('l9', 300)], at(360 + i * 60), { sub: NO, emma: { statusCode: 502 } })).failing);
  assert.deepEqual(fails, [false, false, true, false]);
});
